using UnityEditor;using UnityEngine;using UnityEditor.SceneManagement;using System.Linq;using System.Collections.Generic;
public static class RebindBunnyToBase{
[MenuItem("Tools/Character/Rebind Bunny Mesh To Base Bones")]
static void Run(){var bunny=GameObject.Find("body_BunnyGirl");var bas=GameObject.Find("body_Base");if(!bunny||!bas){Debug.LogError("body_BunnyGirl or body_Base not found");return;}var r=bunny.GetComponentsInChildren<SkinnedMeshRenderer>(true).First();var map=bas.GetComponentsInChildren<Transform>(true).ToDictionary(x=>x.name,x=>x);var list=new List<Transform>();foreach(var old in r.bones){string n=old.name.Replace("Character1_","");if(n=="RightShoulder")n="Clavicle_R";if(n=="LeftShoulder")n="Clavicle_L";if(n=="RightArm")n="Upper_Arm_R";if(n=="LeftArm")n="Upper_Arm_L";if(n=="RightForeArm")n="Lower_Arm_R";if(n=="LeftForeArm")n="Lower_Arm_L";if(n=="RightHand")n="Hand_R";if(n=="LeftHand")n="Hand_L";if(n=="RightUpLeg")n="Upper_Leg_R";if(n=="LeftUpLeg")n="Upper_Leg_L";if(n=="RightLeg")n="Lower_Leg_R";if(n=="LeftLeg")n="Lower_Leg_L";if(n=="RightFoot")n="Foot_R";if(n=="LeftFoot")n="Foot_L";if(n=="Spine1")n="Chest";if(n=="Spine2")n="Upper_Chest";Transform t;map.TryGetValue(n,out t);list.Add(t??old);}r.bones=list.ToArray();if(map.ContainsKey("Hips"))r.rootBone=map["Hips"];var a=bunny.GetComponent<Animator>();if(a)a.enabled=false;EditorSceneManager.MarkSceneDirty(bunny.scene);Debug.Log("Rebound Bunny mesh bones to body_Base; Bunny Animator disabled.");}}